set-variable.value:
@{
            string first = (string)context.Variables["speech-backend-counter"] == "0" ? "0" : "1";
            string second = first == "0" ? "1" : "0";
            if ((bool)context.Variables["speech-ok-" + first]) { return first; }
            if ((bool)context.Variables["speech-ok-" + second]) { return second; }
            return "none";
        }

set-header.value:
@{
                            long a, b;
                            long.TryParse(context.Variables["speech-cd-0"].ToString(), out a);
                            long.TryParse(context.Variables["speech-cd-1"].ToString(), out b);
                            double secs = (Math.Min(a, b) - DateTime.UtcNow.Ticks) / (double)TimeSpan.TicksPerSecond;
                            return Math.Max(1, (int)Math.Ceiling(secs)).ToString();
                        }

set-variable.value:
@{
                    int s;
                    if (!int.TryParse(context.Response.Headers.GetValueOrDefault("Retry-After", ""), out s)) { s = 30; }
                    return Math.Min(Math.Max(s, 5), 300);
                }

set-header.value:
@{
                        string other = (string)context.Variables["speech-target"] == "0" ? "1" : "0";
                        if ((bool)context.Variables["speech-ok-" + other]) { return "0"; }
                        long until;
                        long.TryParse(context.Variables["speech-cd-" + other].ToString(), out until);
                        int otherSecs = (int)Math.Ceiling((until - DateTime.UtcNow.Ticks) / (double)TimeSpan.TicksPerSecond);
                        return Math.Max(1, Math.Min((int)context.Variables["speech-cd-secs"], otherSecs)).ToString();
                    }
